const PAIR_TL  = ["torvalds", "liskov"]
const REVIEW_SCHEMA = {"type": "object", "properties": {"issues": {"type": "array", "items": {"type": "object", "properties": {"severity": {"type": "string", "enum": ["P0", "P1", "P2"]}, "description": {"type": "string"}, "detail": {"type": "string"}, "file": {"type": ["string", "null"]}, "lines": {"type": ["string", "null"]}, "flagged_by": {"type": "array", "items": {"type": "string"}}}, "required": ["severity", "description", "flagged_by"]}}, "dissents": {"type": "array"}, "summary": {"type": "string"}}, "required": ["issues", "summary"]}
const JUDGE_SCHEMA  = {"type": "object", "properties": {"verdicts": {"type": "array", "items": {"type": "object", "properties": {"index": {"type": "integer"}, "label": {"type": "string", "enum": ["CONFIRMED", "PLAUSIBLE", "FABRICATED"]}, "reason": {"type": "string"}}, "required": ["index", "label", "reason"]}}, "ground_truth_recall": {"type": "object", "properties": {"total_human_comments": {"type": "integer"}, "comments_matched_by_ai": {"type": "integer"}, "comments_missed": {"type": "array", "items": {"type": "string"}}}, "required": ["total_human_comments", "comments_matched_by_ai", "comments_missed"]}}, "required": ["verdicts", "ground_truth_recall"]}
